.ba{position:absolute;left:70px;right:70px;top:520px;height:1000px;border-radius:44px;overflow:hidden;box-shadow:0 0 0 2px color-mix(in srgb,var(--rf-text) 8%,transparent);animation:k-rise .9s cubic-bezier(.16,1,.3,1) 0.35s both}
